dtsPropsFor.ResultMark:
/** `true` won · `false` lost · `null` level — a dual that finished level on lines. An undecided cell draws `EmptyMark` instead. */
won: boolean | null;
className?: string;

dtsPropsFor.PlayerMark:
name: string;
/** Pass only on the viewer's own row; `null` on everyone else's. */
viewer: { initials: string; avatarUrl: string | null } | null;
/** A teammate's photo; ignored on the viewer's own row. */
photoUrl?: string | null;

dtsPropsFor.ScoreLine:
/** Resolved, pre-oriented sets: `player1` is the side the row is about. Tiebreak values are POINTS, not games. */
sets: { player1: number; player2: number; player1Tiebreak?: number | null; player2Tiebreak?: number | null }[];
className?: string;
style?: React.CSSProperties;

dtsPropsFor.WorkspaceMark:
/** `kind` picks the letter's ground (team = ink, personal = blue); `iconUrl` draws a crest or photo instead of `mark`. */
workspace: { kind: "personal" | "team"; mark: string; iconUrl?: string | null };
/** Size, radius and letter type, e.g. `size-[26px] rounded-[6px] text-[11px]`. */
className?: string;

dtsPropsFor.CardEmpty:
/** Screen-reader sentence for the dimmed ghost block. */
description: string;
/** The band under the hairline: a title, one sentence, at most one outline action. */
band: { title: string; body: string; action?: { label: string; href: string } };
className?: string;
/** The card's own shape, drawn grey — ghost rows, an empty court. */
children: React.ReactNode;

dtsPropsFor.MenuSelect:
/** Accessible name — the visible caption or row label sits beside it. */
label: string;
/** `undefined` is a real state (an unanswered field): no row is chosen and `placeholder` shows. */
value: string | undefined;
options: readonly { value: string; label: string; description?: string }[];
onChange: (next: string) => void;
/** `pill` (30px bordered, default) · `underline` (a form field) · `text` (a value inside a table row). */
variant?: "pill" | "underline" | "text";
/** Sentence under a hairline at the menu's foot. */
note?: string;
disabled?: boolean;
className?: string;
/** Menu width. Defaults to the trigger's width for `underline`, 232px for `pill`. */
width?: number | "trigger";
placeholder?: string;
align?: "start" | "end";
/** Caps the menu at 360px and scrolls the rest. */
scroll?: boolean;

dtsPropsFor.DateField:
/** Accessible name — the visible eyebrow or row label sits outside. */
label: string;
/** `YYYY-MM-DD`, or `""` for empty. Never `null`. */
value: string;
/** Receives `YYYY-MM-DD`, or `""` when the field is cleared. */
onChange: (next: string) => void;
/** `underline` (34px form field, default) · `boxed` (30px bordered) · `bare` (parent row owns the rule). */
variant?: "boxed" | "underline" | "bare";
/** `YYYY-MM-DD`; earlier days are unpickable. */
min?: string;
/** `YYYY-MM-DD`; later days are unpickable. */
max?: string;
disabled?: boolean;
required?: boolean;
className?: string;
/** Filled with `{ focus() }` so a dialog can send focus here as the first invalid field. */
handleRef?: React.RefObject<{ focus: () => void } | null>;
/** Fires when the field starts or stops showing a blank segment; refuse the submit while true. */
onIncompleteChange?: (incomplete: boolean) => void;
